def format_hex_id(n, width):
    digits = "0123456789abcdef"
    if n == 0:
        s = "0"
    else:
        s = ""
        x = n
        while x > 0:
            s = digits[x % 16] + s
            x //= 16
    return s.rjust(width, '0')

