def sanitize_filename_windows(name):
    reserved_chars = '<>:"/\\|?*'
    table = str.maketrans({c: '_' for c in reserved_chars})
    replaced = name.translate(table)
    trailing = ' .'
    return replaced.rstrip(trailing)

def average_by_key_from_pairs(pairs):
    keys = []
    for k, _ in pairs:
        if k not in keys:
            keys.append(k)
    result = {}
    for k in keys:
        values = [v for key, v in pairs if key == k]
        result[k] = round(sum(values) / len(values), 2)
    return result

