        ((('a', 1),), (('a', 2),), (('b', 3),)): {'a': 3},
        ((('x', 1),), (('y', 2),)): {},
        (): {},
    }
    try:
        marker = tuple(tuple(sorted(d.items())) for d in dicts_list)
