def format_id_suffixed(n, width, suffix):
    sign = '-' if n < 0 else ''
    digits = str(abs(n))
    if len(digits) < width - len(sign):
        digits = '0' * (width - len(sign) - len(digits)) + digits
    return sign + digits + suffix

