def oxford_join(items):
    n = len(items)
    if n == 0:
        return ''
    if n == 1:
        return items[0]
    *head, tail = items
    if n == 2:
        return f'{head[0]} and {tail}'
    return ', '.join(head) + f', and {tail}'

